using System.Globalization;
using Dip.Application.Abstractions.Persistence;
using Dip.Application.Abstractions.Spreadsheets;
using Dip.Application.Abstractions.Time;
using Dip.Application.Features.Milestones;
using Dip.Domain.Enums;

namespace Dip.Application.Features.Management;

public sealed class ManagementSpreadsheetService
{
    public static readonly string[] EditableSheets=["Teams","Workstreams","Tasks","Milestones","Blockers","Requirements","Dependencies","ScopeBaselines"];
    private readonly IDevelopmentGraphRepository _repo;private readonly WorkManagementService _work;private readonly ManagementAnalyticsService _analytics;private readonly MilestoneIntelligenceService _milestones;private readonly IGoogleSheetsConnector _google;private readonly ISystemClock _clock;
    public ManagementSpreadsheetService(IDevelopmentGraphRepository repo,WorkManagementService work,ManagementAnalyticsService analytics,MilestoneIntelligenceService milestones,IGoogleSheetsConnector google,ISystemClock clock){_repo=repo;_work=work;_analytics=analytics;_milestones=milestones;_google=google;_clock=clock;}

    public async Task<ManagementWorkbookDto> BuildWorkbookAsync(Guid projectId,CancellationToken ct)
    {
        var nodes=await _repo.ListNodesAsync(projectId,null,ct);var capacity=await _analytics.GetCapacityAsync(projectId,8,ct);var schedule=await _analytics.GetScheduleAsync(projectId,ct);var blockers=await _analytics.GetBlockersAsync(projectId,ct);var deps=await _analytics.GetDependenciesAsync(projectId,ct);var milestoneSummary=await _analytics.GetMilestonesAsync(projectId,ct);var scope=await _analytics.GetScopeAsync(projectId,ct);var sheets=new List<SpreadsheetSheetDto>();
        var maxUtil=capacity.Teams.Count==0?0m:capacity.Teams.Max(x=>x.UtilizationPercent);var health=schedule.Status=="Blocked"||blockers.Critical>0?"Critical":schedule.Status=="AtRisk"||maxUtil>100m||scope.ScopeGrowthPercent>10m?"AtRisk":"Healthy";
        sheets.Add(Sheet("Executive",["Metric","Value","Management meaning"],[
            ["Project health",health,"Overall management status derived from schedule, blockers, capacity and scope."],
            ["Forecast finish",schedule.ForecastFinishUtc?.ToString("yyyy-MM-dd",CultureInfo.InvariantCulture)??"Not available","Current dependency-aware finish forecast."],
            ["Forecast delay (days)",schedule.DelayDays.ToString(CultureInfo.InvariantCulture),"Difference between planned and forecast finish."],
            ["Open blockers",blockers.Open.ToString(CultureInfo.InvariantCulture),"Items preventing work from flowing."],
            ["Critical blockers",blockers.Critical.ToString(CultureInfo.InvariantCulture),"Blockers requiring immediate management attention."],
            ["Peak team utilization %",F(maxUtil),"Over 100% indicates planned demand exceeds available capacity."],
            ["Scope growth %",F(scope.ScopeGrowthPercent),"Growth from the latest scope baseline."],
            ["Milestones at risk",milestoneSummary.AtRisk.ToString(CultureInfo.InvariantCulture),"Milestones likely to miss current expectations."],
            ["Milestones blocked",milestoneSummary.Blocked.ToString(CultureInfo.InvariantCulture),"Milestones directly or indirectly blocked."],
            ["Critical-path items",schedule.CriticalItems.ToString(CultureInfo.InvariantCulture),"Items with no calculated schedule slack."]
        ]));
        sheets.Add(Sheet("Teams",["Key","Name","CapacityHoursPerWeek","BufferPercent","Status"],nodes.Where(x=>x.Type==DevelopmentGraphNodeType.Team).OrderBy(x=>x.Name).Select(x=>(IReadOnlyList<string>)[WorkManagementService.Strip(x.Key),x.Name,F(WorkManagementService.MetaDecimal(x,"CapacityHoursPerWeek")),F(WorkManagementService.MetaDecimal(x,"BufferPercent",10m)),x.Status]).ToArray(),true));
        sheets.Add(Sheet("Workstreams",["Key","Name","TeamKey","PlannedCapacityHoursPerWeek","PlannedStart","Due","CompletionPercent","Status"],nodes.Where(x=>x.Type==DevelopmentGraphNodeType.Workstream).OrderBy(x=>x.Name).Select(x=>(IReadOnlyList<string>)[WorkManagementService.Strip(x.Key),x.Name,WorkManagementService.MetaString(x,"TeamKey"),F(WorkManagementService.MetaDecimal(x,"PlannedCapacityHoursPerWeek")),D(WorkManagementService.MetaDate(x,"PlannedStartUtc",x.FirstObservedAtUtc)),D(WorkManagementService.MetaDate(x,"DueAtUtc",x.LastObservedAtUtc)),F(WorkManagementService.MetaDecimal(x,"CompletionPercent")),x.Status]).ToArray(),true));
        sheets.Add(Sheet("Tasks",["Key","Name","WorkstreamKey","EstimateHours","RemainingHours","PlannedStart","Due","CompletionPercent","Status","Priority","OwnerLabel","ExternalReference"],nodes.Where(x=>x.Type==DevelopmentGraphNodeType.Task).OrderBy(x=>x.Name).Select(x=>(IReadOnlyList<string>)[WorkManagementService.Strip(x.Key),x.Name,WorkManagementService.MetaString(x,"WorkstreamKey"),F(WorkManagementService.MetaDecimal(x,"EstimateHours")),F(WorkManagementService.MetaDecimal(x,"RemainingHours")),D(WorkManagementService.MetaDate(x,"PlannedStartUtc",x.FirstObservedAtUtc)),D(WorkManagementService.MetaDate(x,"DueAtUtc",x.LastObservedAtUtc)),F(WorkManagementService.MetaDecimal(x,"CompletionPercent")),x.Status,WorkManagementService.MetaString(x,"Priority","Medium"),WorkManagementService.MetaString(x,"OwnerLabel"),x.ExternalReference??""]).ToArray(),true));
        sheets.Add(Sheet("Schedule",["Type","Key","Name","Workstream","PlannedStart","Due","ForecastFinish","DurationDays","CompletionPercent","Status","SlackDays","Critical","BlockedBy"],schedule.Items.Select(x=>(IReadOnlyList<string>)[x.Type,x.Key,x.Name,x.WorkstreamKey,D(x.PlannedStartUtc),D(x.DueAtUtc),D(x.ForecastFinishUtc),x.DurationDays.ToString(CultureInfo.InvariantCulture),F(x.CompletionPercent),x.Status,x.SlackDays.ToString(CultureInfo.InvariantCulture),x.IsCritical?"Yes":"No",x.BlockedByCount.ToString(CultureInfo.InvariantCulture)]).ToArray()));
        sheets.Add(BuildGanttSheet(schedule));
        sheets.Add(Sheet("Milestones",["Key","Name","PlannedStart","Due","DurationDays","CompletionPercent","State","ExternalReference"],nodes.Where(x=>x.Type==DevelopmentGraphNodeType.Milestone).OrderBy(x=>WorkManagementService.MetaDate(x,"DueAtUtc",DateTimeOffset.MaxValue)).Select(x=>(IReadOnlyList<string>)[WorkManagementService.Strip(x.Key),x.Name,D(WorkManagementService.MetaDate(x,"PlannedStartUtc",x.FirstObservedAtUtc)),D(WorkManagementService.MetaDate(x,"DueAtUtc",x.LastObservedAtUtc)),((int)WorkManagementService.MetaDecimal(x,"DurationDays",1m)).ToString(CultureInfo.InvariantCulture),F(WorkManagementService.MetaDecimal(x,"CompletionPercent")),x.Status,x.ExternalReference??""]).ToArray(),true));
        var blockerImpact=blockers.Items.ToDictionary(x=>x.Key,StringComparer.OrdinalIgnoreCase);
        sheets.Add(Sheet("Blockers",["Key","Title","Reason","Severity","OpenedAt","Status","BlockedTasks","BlockedWorkstreams","BlockedMilestones","AgeDays","DownstreamAffected","ManagementAction"],nodes.Where(x=>x.Type==DevelopmentGraphNodeType.Blocker).OrderBy(x=>x.Name).Select(x=>{var key=WorkManagementService.Strip(x.Key);blockerImpact.TryGetValue(key,out var impact);return (IReadOnlyList<string>)[key,x.Name,WorkManagementService.MetaString(x,"Reason"),WorkManagementService.MetaString(x,"Severity","Medium"),D(WorkManagementService.MetaDate(x,"OpenedAtUtc",x.FirstObservedAtUtc)),x.Status,string.Join(";",WorkManagementService.MetaStringArray(x,"BlockedTaskKeys")),string.Join(";",WorkManagementService.MetaStringArray(x,"BlockedWorkstreamKeys")),string.Join(";",WorkManagementService.MetaStringArray(x,"BlockedMilestoneKeys")),(impact?.AgeDays??0).ToString(CultureInfo.InvariantCulture),(impact?.DownstreamAffected??0).ToString(CultureInfo.InvariantCulture),impact?.ManagementAction??""];}).ToArray(),true));
        sheets.Add(Sheet("Dependencies",["SourceType","SourceKey","SourceName","TargetType","TargetKey","TargetName","Relation","Critical","CrossWorkstream"],deps.Dependencies.Select(x=>(IReadOnlyList<string>)[x.SourceType,x.SourceKey,x.SourceName,x.TargetType,x.TargetKey,x.TargetName,x.Relation,x.Critical?"Yes":"No",x.CrossWorkstream?"Yes":"No"]).ToArray(),true));
        sheets.Add(Sheet("Requirements",["Key","Title","Priority","Status","ScopeState","CompletionPercent","AcceptanceSummary","ExternalReference"],scope.Requirements.Select(x=>(IReadOnlyList<string>)[x.Key,x.Title,x.Priority,x.Status,x.ScopeState,F(x.CompletionPercent),x.AcceptanceSummary??"",x.ExternalReference??""]).ToArray(),true));
        sheets.Add(Sheet("Scope",["Metric","Value"],[
            ["Baseline",scope.BaselineKey??"None"],["BaselineRequirements",scope.BaselineRequirements.ToString(CultureInfo.InvariantCulture)],["CurrentIncludedRequirements",scope.CurrentIncludedRequirements.ToString(CultureInfo.InvariantCulture)],["AddedAfterBaseline",scope.AddedAfterBaseline.ToString(CultureInfo.InvariantCulture)],["DeferredOrRemoved",scope.DeferredOrRemoved.ToString(CultureInfo.InvariantCulture)],["ScopeGrowthPercent",F(scope.ScopeGrowthPercent)],["IncompleteHighPriority",scope.IncompleteHighPriority.ToString(CultureInfo.InvariantCulture)]
        ]));
        sheets.Add(Sheet("Capacity",["Level","Key","Name","CapacityHours","RemainingHours","UtilizationPercent","ActiveTasks","BlockedTasks","Status"],capacity.Teams.Select(x=>(IReadOnlyList<string>)["Team",x.Key,x.Name,F(x.CapacityHours),F(x.RemainingHours),F(x.UtilizationPercent),x.ActiveTasks.ToString(CultureInfo.InvariantCulture),x.BlockedTasks.ToString(CultureInfo.InvariantCulture),x.Status]).Concat(capacity.Workstreams.Select(x=>(IReadOnlyList<string>)["Workstream",x.Key,x.Name,F(x.CapacityHours),F(x.RemainingHours),F(x.UtilizationPercent),x.ActiveTasks.ToString(CultureInfo.InvariantCulture),x.BlockedTasks.ToString(CultureInfo.InvariantCulture),x.Status])).ToArray()));
        sheets.Add(BuildWorkloadSheet(capacity));
        sheets.Add(Sheet("ScopeBaselines",["Key","Name","CapturedAt","BaselineRequirements"],nodes.Where(x=>x.Type==DevelopmentGraphNodeType.ScopeBaseline).OrderByDescending(x=>x.LastObservedAtUtc).Select(x=>(IReadOnlyList<string>)[WorkManagementService.Strip(x.Key),x.Name,D(WorkManagementService.MetaDate(x,"CapturedAtUtc",x.FirstObservedAtUtc)),F(WorkManagementService.MetaDecimal(x,"BaselineRequirements"))]).ToArray(),true));
        sheets.Add(Sheet("RawGraph",["Type","Key","Name","Status","Provider","ExternalReference","LastObservedUtc"],nodes.OrderBy(x=>x.Type).ThenBy(x=>x.Name).Select(x=>(IReadOnlyList<string>)[x.Type.ToString(),WorkManagementService.Strip(x.Key),x.Name,x.Status,x.Provider??"",x.ExternalReference??"",x.LastObservedAtUtc.ToString("O",CultureInfo.InvariantCulture)]).ToArray()));
        return new(projectId,sheets,_clock.UtcNow);
    }

    public async Task<byte[]> ExportXlsxAsync(Guid projectId,CancellationToken ct)=>ManagementXlsxCodec.Write(await BuildWorkbookAsync(projectId,ct));
    public async Task<SpreadsheetImportResult> ImportXlsxAsync(Guid projectId,Stream stream,CancellationToken ct)=>await ApplyRowsAsync(projectId,ManagementXlsxCodec.Read(stream),ct);

    public async Task<GoogleSheetsSyncResult> SyncGoogleAsync(GoogleSheetsSyncCommand c,CancellationToken ct)
    {
        if(c.ProjectId==Guid.Empty)throw new ArgumentException("ProjectId is required.",nameof(c));var warnings=new List<string>();SpreadsheetImportResult? imported=null;var pulled=0;var pushed=0;
        await _google.EnsureSheetsAsync(c.SpreadsheetId,c.AccessToken,(await BuildWorkbookAsync(c.ProjectId,ct)).Sheets.Select(x=>x.Name).ToArray(),ct);
        if(c.PullEditableSheets){var rows=await _google.PullAsync(c.SpreadsheetId,c.AccessToken,EditableSheets,ct);pulled=rows.Count;imported=await ApplyRowsAsync(c.ProjectId,rows,ct);warnings.AddRange(imported.Warnings);}
        if(c.PushCalculatedSheets){var workbook=await BuildWorkbookAsync(c.ProjectId,ct);var targets=c.PullEditableSheets?workbook.Sheets:workbook.Sheets.Where(x=>!x.Editable).ToArray();var grids=targets.Select(x=>new GoogleSheetGrid(x.Name,new List<IReadOnlyList<string>>{x.Headers}.Concat(x.Rows).ToArray())).ToArray();await _google.PushAsync(c.SpreadsheetId,c.AccessToken,grids,ct);pushed=grids.Length;}
        return new(pulled,pushed,imported,warnings.Distinct().ToArray(),_clock.UtcNow);
    }

    public async Task<SpreadsheetImportResult> ApplyRowsAsync(Guid projectId,IReadOnlyDictionary<string,IReadOnlyList<IReadOnlyList<string>>> tables,CancellationToken ct)
    {
        var warnings=new List<string>();var teamCount=0;var wsCount=0;var taskCount=0;var milestoneCount=0;var blockerCount=0;var reqCount=0;
        foreach(var row in Data(tables,"Teams")){try{await _work.UpsertTeamAsync(new(projectId,V(row,"Key"),V(row,"Name"),Dec(row,"CapacityHoursPerWeek"),Dec(row,"BufferPercent",10m),V(row,"Status","Active")),ct);teamCount++;}catch(Exception ex){warnings.Add("Teams: "+ex.Message);}}
        foreach(var row in Data(tables,"Workstreams")){try{await _work.UpsertWorkstreamAsync(new(projectId,V(row,"Key"),V(row,"Name"),V(row,"TeamKey"),Dec(row,"PlannedCapacityHoursPerWeek"),Date(row,"PlannedStart"),Date(row,"Due"),Dec(row,"CompletionPercent"),V(row,"Status","Active")),ct);wsCount++;}catch(Exception ex){warnings.Add("Workstreams: "+ex.Message);}}
        foreach(var row in Data(tables,"Tasks")){try{await _work.UpsertTaskAsync(new(projectId,V(row,"Key"),V(row,"Name"),V(row,"WorkstreamKey"),Dec(row,"EstimateHours"),Dec(row,"RemainingHours"),Date(row,"PlannedStart"),Date(row,"Due"),Dec(row,"CompletionPercent"),V(row,"Status","Planned"),V(row,"Priority","Medium"),Null(V(row,"OwnerLabel")),Null(V(row,"ExternalReference"))),ct);taskCount++;}catch(Exception ex){warnings.Add("Tasks: "+ex.Message);}}
        foreach(var row in Data(tables,"Milestones")){try{var state=Enum.TryParse<MilestoneState>(V(row,"State","Planned"),true,out var parsed)?parsed:MilestoneState.Planned;await _milestones.UpsertAsync(new(projectId,V(row,"Key"),V(row,"Name"),Date(row,"PlannedStart"),Date(row,"Due"),(int)Dec(row,"DurationDays",1m),Dec(row,"CompletionPercent"),state,Null(V(row,"ExternalReference"))),ct);milestoneCount++;}catch(Exception ex){warnings.Add("Milestones: "+ex.Message);}}
        foreach(var row in Data(tables,"Blockers")){try{await _work.UpsertBlockerAsync(new(projectId,V(row,"Key"),V(row,"Title"),V(row,"Reason"),V(row,"Severity","Medium"),Date(row,"OpenedAt",_clock.UtcNow),V(row,"Status","Open"),Split(row,"BlockedTasks"),Split(row,"BlockedWorkstreams"),Split(row,"BlockedMilestones")),ct);blockerCount++;}catch(Exception ex){warnings.Add("Blockers: "+ex.Message);}}
        foreach(var row in Data(tables,"Requirements")){try{await _work.UpsertRequirementAsync(new(projectId,V(row,"Key"),V(row,"Title"),V(row,"Priority","Medium"),V(row,"Status","Planned"),V(row,"ScopeState","Included"),Dec(row,"CompletionPercent"),Null(V(row,"AcceptanceSummary")),Null(V(row,"ExternalReference"))),ct);reqCount++;}catch(Exception ex){warnings.Add("Requirements: "+ex.Message);}}
        foreach(var row in Data(tables,"Dependencies")){try{var relation=V(row,"Relation","Blocks");var sourceType=V(row,"SourceType");var targetType=V(row,"TargetType");if(relation.Equals("ScheduledFor",StringComparison.OrdinalIgnoreCase)&&sourceType.Equals("Task",StringComparison.OrdinalIgnoreCase)&&targetType.Equals("Milestone",StringComparison.OrdinalIgnoreCase))await _work.LinkTaskToMilestoneAsync(new(projectId,V(row,"SourceKey"),V(row,"TargetKey")),ct);else if(relation.Equals("Satisfies",StringComparison.OrdinalIgnoreCase)&&targetType.Equals("Requirement",StringComparison.OrdinalIgnoreCase))await _work.LinkRequirementAsync(new(projectId,V(row,"TargetKey"),sourceType,V(row,"SourceKey")),ct);else await _work.LinkDependencyAsync(new(projectId,sourceType,V(row,"SourceKey"),targetType,V(row,"TargetKey"),V(row,"Critical","No").Equals("Yes",StringComparison.OrdinalIgnoreCase)),ct);}catch(Exception ex){warnings.Add("Dependencies: "+ex.Message);}}
        foreach(var row in Data(tables,"ScopeBaselines")){try{var key=V(row,"Key");if(!string.IsNullOrWhiteSpace(key))await _work.CreateScopeBaselineAsync(new(projectId,key,V(row,"Name",key),Date(row,"CapturedAt",_clock.UtcNow)),ct);}catch(Exception ex){warnings.Add("ScopeBaselines: "+ex.Message);}}
        return new(teamCount,wsCount,taskCount,milestoneCount,blockerCount,reqCount,warnings.Take(100).ToArray());
    }

    private static SpreadsheetSheetDto BuildWorkloadSheet(CapacityOverviewDto capacity)
    {
        var starts=capacity.Teams.SelectMany(x=>x.Weekly).Select(x=>x.WeekStartUtc).Concat(capacity.Workstreams.SelectMany(x=>x.Weekly).Select(x=>x.WeekStartUtc)).Distinct().OrderBy(x=>x).ToArray();var headers=new List<string>{"Level","Key","Name"};headers.AddRange(starts.Select(x=>x.ToString("MM-dd",CultureInfo.InvariantCulture)));var rows=new List<IReadOnlyList<string>>();foreach(var t in capacity.Teams){var row=new List<string>{"Team",t.Key,t.Name};row.AddRange(starts.Select(s=>F(t.Weekly.FirstOrDefault(w=>w.WeekStartUtc==s)?.UtilizationPercent??0m)));rows.Add(row);}foreach(var w in capacity.Workstreams){var row=new List<string>{"Workstream",w.Key,w.Name};row.AddRange(starts.Select(s=>F(w.Weekly.FirstOrDefault(b=>b.WeekStartUtc==s)?.UtilizationPercent??0m)));rows.Add(row);}return Sheet("Workload",headers,rows);
    }

    private static SpreadsheetSheetDto BuildGanttSheet(ManagementScheduleDto schedule)
    {
        if(schedule.Items.Count==0)return Sheet("Gantt",["Type","Key","Name"],[]);
        var start=StartOfWeek(schedule.Items.Min(x=>x.PlannedStartUtc));var end=schedule.Items.Max(x=>x.ForecastFinishUtc);var weeks=Math.Clamp((int)Math.Ceiling(Math.Max(1d,(end-start).TotalDays)/7d),1,26);var headers=new List<string>{"Type","Key","Name"};for(var i=0;i<weeks;i++)headers.Add(start.AddDays(i*7).ToString("MM-dd",CultureInfo.InvariantCulture));var rows=new List<IReadOnlyList<string>>();foreach(var item in schedule.Items.OrderBy(x=>x.PlannedStartUtc).ThenBy(x=>x.Name)){var row=new List<string>{item.Type,item.Key,item.Name};for(var i=0;i<weeks;i++){var ws=start.AddDays(i*7);var we=ws.AddDays(7);row.Add(item.PlannedStartUtc<we&&item.ForecastFinishUtc>=ws?(item.IsCritical?"CRITICAL":"■"):"");}rows.Add(row);}return Sheet("Gantt",headers,rows);
    }
    private static DateTimeOffset StartOfWeek(DateTimeOffset value){var d=value.UtcDateTime.Date;var offset=((int)d.DayOfWeek+6)%7;return new DateTimeOffset(d.AddDays(-offset),TimeSpan.Zero);}
    private static SpreadsheetSheetDto Sheet(string name,IReadOnlyList<string> headers,IReadOnlyList<IReadOnlyList<string>> rows,bool editable=false)=>new(name,headers,rows,editable);
    private static IEnumerable<IReadOnlyDictionary<string,string>> Data(IReadOnlyDictionary<string,IReadOnlyList<IReadOnlyList<string>>> tables,string name){if(!tables.TryGetValue(name,out var rows)||rows.Count<2)return [];var headers=rows[0].Select(x=>x.Trim()).ToArray();return rows.Skip(1).Where(r=>r.Any(x=>!string.IsNullOrWhiteSpace(x))).Select(r=>(IReadOnlyDictionary<string,string>)headers.Select((h,i)=>(h,v:i<r.Count?r[i]:"")).Where(x=>!string.IsNullOrWhiteSpace(x.h)).ToDictionary(x=>x.h,x=>x.v,StringComparer.OrdinalIgnoreCase)).ToArray();}
    private static string V(IReadOnlyDictionary<string,string> row,string key,string fallback="")=>row.TryGetValue(key,out var value)&&!string.IsNullOrWhiteSpace(value)?value.Trim():fallback;
    private static decimal Dec(IReadOnlyDictionary<string,string> row,string key,decimal fallback=0m)=>decimal.TryParse(V(row,key),NumberStyles.Any,CultureInfo.InvariantCulture,out var x)?x:decimal.TryParse(V(row,key),NumberStyles.Any,CultureInfo.CurrentCulture,out x)?x:fallback;
    private static DateTimeOffset Date(IReadOnlyDictionary<string,string> row,string key)=>Date(row,key,DateTimeOffset.UtcNow);
    private static DateTimeOffset Date(IReadOnlyDictionary<string,string> row,string key,DateTimeOffset fallback)=>DateTimeOffset.TryParse(V(row,key),CultureInfo.InvariantCulture,DateTimeStyles.AssumeUniversal,out var x)?x:DateTimeOffset.TryParse(V(row,key),out x)?x:fallback;
    private static string[] Split(IReadOnlyDictionary<string,string> row,string key)=>V(row,key).Split([';',','],StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries);
    private static string? Null(string s)=>string.IsNullOrWhiteSpace(s)?null:s;
    private static string F(decimal x)=>x.ToString("0.##",CultureInfo.InvariantCulture);
    private static string D(DateTimeOffset x)=>x==DateTimeOffset.MaxValue?"":x.ToString("yyyy-MM-dd",CultureInfo.InvariantCulture);
}
